/**
 * Envuelve el ítem que armó PostgreSQL con el tipo de la lista. No traduce
 * nada: la traducción vive en helpdesk.item_espejo_sharepoint.
 */
const row = $input.first().json;
const item = typeof row.item === "string" ? JSON.parse(row.item) : row.item;

return [
  {
    json: {
      id_sync: row.id_sync,
      id_ticket: row.id_ticket,
      operation: row.operation,
      claimed_at: row.claimed_at,
      sp_id: row.sp_id,
      espejo_modified: row.espejo_modified,
      codigo_ticket: row.codigo_ticket,
      sharepointBody: {
        __metadata: { type: "SP.Data.HelpDeskBdListItem" },
        ...item,
      },
    },
  },
];

/**
 * Resultado de la escritura en SharePoint, para crear o para actualizar.
 * Los dos nodos HTTP continúan ante error (onError: continueRegularOutput),
 * así que un fallo llega aquí como json.error y no detiene el lote.
 *
 * - CREATE: SharePoint devuelve el ítem; su Id es el sp_id.
 * - UPDATE (MERGE): SharePoint responde 204 sin cuerpo; el sp_id ya se sabía.
 */
const map = $("Code - Map SharePoint Fields").item.json;
const res = $input.first().json ?? {};
const failed = res.error !== undefined;

let spId = map.sp_id;
if (map.operation === "CREATE_TICKET") {
  const raw = res.d?.Id ?? res.d?.ID ?? res.Id ?? res.ID ?? null;
  spId = raw === null ? null : Number(raw);
}

const ok = !failed && spId !== null && Number.isFinite(Number(spId));
const errorMessage = failed
  ? String(res.error?.message ?? res.error ?? "Error de SharePoint")
  : ok
    ? null
    : "SharePoint no devolvió el id del ítem.";

return [
  {
    json: {
      id_sync: map.id_sync,
      id_ticket: map.id_ticket,
      operation: map.operation,
      claimed_at: map.claimed_at,
      codigo_ticket: map.codigo_ticket,
      sp_id: ok ? Number(spId) : null,
      ok,
      error_message: errorMessage,
    },
  },
];

/**
 * Genera N "slots" de procesamiento.
 *
 * Cada slot intentará reclamar 1 ticket pendiente.
 * Si en algún slot ya no hay pendientes, el workflow termina.
 */
const maxItemsPerRun = 20;

return Array.from({ length: maxItemsPerRun }, (_, index) => ({
  json: {
    slot: index + 1,
    maxItemsPerRun,
  },
}));

/**
 * Antes de actualizar un ítem: ¿lo cambió alguien en PowerApps después de la
 * última lectura base del espejo? Si sí, no se escribe. Sobrescribirlo
 * borraría ese cambio antes de que la ingesta lo vea, sin dejar rastro. El
 * envío queda FAILED con CONFLICTO_POWERAPPS y se reintenta cuando la
 * ingesta ya lo concilió (PG - Requeue Stale Processing, paso 2).
 *
 * Si no, se escribe con la etag de esta lectura (IF-MATCH): si alguien lo
 * cambia entre esta lectura y la escritura, SharePoint responde 412 y el
 * envío falla en vez de pisar el cambio.
 */
const map = $("Code - Map SharePoint Fields").item.json;
const current = $input.first().json ?? {};

if (current.error !== undefined) {
  return [{ json: { ...map, safe: false, ok: false, error_message: "No se pudo leer el ítem antes de actualizarlo: " + String(current.error?.message ?? current.error) } }];
}

const item = current.d ?? current;
const modified = item.Modified ? Date.parse(item.Modified) : NaN;
const base = map.espejo_modified ? Date.parse(map.espejo_modified) : NaN;

if (Number.isFinite(base) && Number.isFinite(modified) && modified > base) {
  return [{ json: { ...map, safe: false, ok: false, error_message: "CONFLICTO_POWERAPPS: el ítem se modificó en PowerApps (" + item.Modified + ") después del último envío. Se enviará cuando la ingesta concilie ese cambio." } }];
}

return [{ json: { ...map, safe: true, etag: item.__metadata?.etag ?? "*" } }];
